function hasTargetPath(root: TreeNode | null, target: number): boolean {
  if (!root) return false;
  if (!root.left && !root.right) return root.val === target;
  const rest = target - root.val;
  return hasTargetPath(root.left, rest) || hasTargetPath(root.right, rest);
}

